using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AbsorbCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sentinel/AbsorbCustomDescription", order = 0)]
public class AbsorbCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		AbsorbAction absorbAction = battleAction as AbsorbAction;
		string text = Smart.Format(base.localizationManager.GetLocalizedIfYouDo(), absorbAction.ActionFace.BattleAction.GetActionDescription(absorbAction.ActionFace.ActionValue).LowercaseFirst());
		return Smart.Format(GetRawLocalizedDescription(battleAction), GetAmountWithoutEquation(amountModified)) + "\n" + text;
	}
}
